390	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
391	        let body = self.body();
392	
393	        // Collect captured variables.
394	        let captured = {
395	            let mut visitor = CapturesVisitor::new(Some(&vm.scopes), Capturer::Context);
396	            visitor.visit(body.to_untyped());
397	            visitor.finish()
398	        };
399	
400	        // Define the closure.
401	        let closure = Closure {
402	            node: ClosureNode::Context(self.body().to_untyped().clone()),
